{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Chrysin, a small lipophilic flavone with phenolic hydroxyls, had oral bioavailability estimated at less than 1% in healthy volunteers, demonstrating that polyphenolic natural products can undergo extensive first-pass metabolism and poor systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Peonidin glycosides in humans showed fractional systemic bioavailability of only 0.24–0.48%, directly confirming very low oral bioavailability for related polyphenolic glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Curcumin is documented to have poor oral bioavailability in humans due to poor solubility, chemical instability, and rapid metabolism, supporting a low-bioavailability outcome for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Flavonolignans in patients exhibited very low oral bioavailability inferred from high apparent oral clearances, reinforcing the pattern of poor systemic exposure among polyphenolic natural products.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental evidence, with very high assay-transfer scores, reports very low oral bioavailability for structurally related polyphenolic natural products. The query, a phenolic coumarin, shares the key liability of extensive first-pass conjugation and poor systemic exposure, so low bioavailability (F<20%) is predicted.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for scopoletin itself is provided.",
    "Evidence is derived from flavonoids, anthocyanins, curcuminoids, and flavonolignans rather than simple coumarins, leaving some uncertainty about the smaller, less polar query structure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

